test('server metrics workshop fallback and small formatted source text keep a 12px floor',async b=>{for(const theme of ['dark','light']){const{page}=await setup(b,theme);await route(page,'servers');await page.evaluate(()=>{const original=chrome.webview.postMessage;chrome.webview.postMessage=m=>{if(m.action==='serverQuery'){sent.push(m);emitNative({id:m.id,ok:true,data:{id:'s1',status:'online',players:1,maxPlayers:32,ping:23,descriptionSource:'server',description:'<RGB:1,0.5,0><SIZE:0.75>small<SIZE:1.3>large<SIZE:0.75>small again<LINE><img src=x onerror=alert(1)>',checkedUtc:'2026-10-15T00:00:00Z'}});return;}original(m);};});await page.locator('[data-server-query="s1"]').click();await page.locator('.server-description summary').click();await page.waitForSelector('[data-rich-size="0.75"]');const supporting=await page.locator('.server-metrics span,.server-metrics small,.server-description [data-rich-size]').evaluateAll(es=>es.map(e=>({text:e.textContent,size:parseFloat(getComputedStyle(e).fontSize)})));assert.ok(supporting.every(x=>x.size>=12),JSON.stringify(supporting));assert.ok(await page.locator('[data-rich-size="1.3"]').evaluate(e=>parseFloat(getComputedStyle(e).fontSize)>12));assert.equal(await page.locator('.server-description span').first().evaluate(e=>getComputedStyle(e).color),'rgb(255, 128, 0)');assert.equal(await page.locator('.server-description img').count(),0);await route(page,'workshop');await page.locator('[data-workshop-tab="subscribed"]').click();await page.waitForSelector('.workshop-neutral small');assert.equal(await page.locator('.workshop-neutral small').count(),1);assert.ok(await page.locator('.workshop-neutral small').evaluateAll(es=>es.every(e=>parseFloat(getComputedStyle(e).fontSize)>=12)));await page.setViewportSize({width:540,height:600});assert.ok(await page.locator('nav button,.header-tools button').evaluateAll(es=>es.every(e=>parseFloat(getComputedStyle(e).fontSize)>=12)));await page.close();}});
