test('selected profile confirmation yields loading and declined consent cancels without resume',async b=>{const{page}=await setup(b);try{await selected(page);await page.evaluate(()=>fx.changes=[{kind:'heap',key:'heapGiB',before:6,after:8}]);await page.locator('#launch').click();await page.locator('#confirm[open]').waitFor();let a=await actions(page);assert.ok(a.indexOf('startupBegin')<a.indexOf('playProfilePreview'));assert.ok(a.includes('startupYield'));await page.locator('#confirm-no').click();await page.waitForFunction(()=>!orange.state.launchAttempt);a=await actions(page);assert.ok(a.includes('startupCancel'));assert.equal(a.includes('startupResume'),false);assert.equal(a.includes('playProfileApply'),false);}finally{await page.close();}});
test('automatic launch submits one native check and structured dependency refusal remains repairable',async b=>{const{page}=await setup(b);try{await page.evaluate(()=>fx.preflight='blocked');await page.locator('#launch').click();await page.waitForFunction(()=>!orange.state.launchAttempt&&!!orange.state.preflight);assert.equal(await page.evaluate(()=>sent.filter(m=>m.action==='launchPreflight').length),0);assert.equal(await page.evaluate(()=>sent.filter(m=>m.action==='launch').length),1);assert.equal(await page.locator('[data-preflight-repair="components"]').count(),1);assert.equal(await page.locator('.preflight-panel details').getAttribute('open'),'');}finally{await page.close();}});
test('target edits cancel an in-flight native preflight attempt before its reply',async b=>{const{page}=await setup(b);try{await page.evaluate(()=>fx.hold='launch');await page.locator('#launch').click();await page.waitForFunction(()=>held.some(m=>m.action==='launch'));await page.locator('#launch-target-kind').selectOption('server');assert.equal(await page.evaluate(()=>sent.filter(m=>m.action==='startupCancel').length),1);assert.deepEqual(await page.evaluate(()=>sent.find(m=>m.action==='startupCancel').payload),{startupId:'0123456789abcdef0123456789abcdef'});await page.evaluate(()=>{fx.hold='';replyNative(held.shift());});await page.waitForFunction(()=>!orange.state.launchAttempt);assert.equal(await page.evaluate(()=>orange.state.launchKind),'server');assert.equal(await page.evaluate(()=>orange.state.preflight),null);}finally{await page.close();}});
for(const mutation of ['recent server','recent save','memory input','memory preset','settings input','reminder input','save detail','server editor','play editor','game epoch'])test('required context change cancels native preflight: '+mutation,async b=>{for(const blocked of [false,true]){const{page}=await setup(b);try{
 await page.evaluate(()=>fx.hold='launch');await page.locator('#launch').click();await page.waitForFunction(()=>held.some(m=>m.action==='launch'));
 if(mutation==='recent server'||mutation==='recent save')await page.locator('[data-recent-target="'+(mutation==='recent server'?'server':'save')+'"]').first().click();
 if(mutation==='memory input'||mutation==='memory preset'){await route(page,'memory');if(mutation==='memory input')await page.locator('#memory-number').fill('12');else await page.locator('[data-memory="12"]').click();}
 if(mutation==='settings input'){await route(page,'settings');await page.locator('[data-setting]').first().selectOption('true');}
 if(mutation==='reminder input')await page.locator('#reminder-minutes').selectOption('60');
 if(mutation==='play editor')await page.locator('[data-play-capture]').click();
 if(mutation==='save detail'){await page.evaluate(()=>fx.saves=[{id:'Sandbox/Test',name:'Test',mode:'Sandbox',editable:true,modCount:1}]);await route(page,'saves');await page.locator('[data-save-open="Sandbox/Test"]').click();}
 if(mutation==='server editor'){await route(page,'servers');await page.locator('[data-server-new]').click();}
 if(mutation==='game epoch')await page.evaluate(()=>orange.acceptStatus({...orange.state.status,gamePath:'Other fixture game',configStamp:'other-config'}));
 assert.equal(await page.evaluate(()=>sent.filter(m=>m.action==='startupCancel').length),1,'invalidate while native is still pending');assert.equal(await page.evaluate(()=>orange.state.launchAttempt.cancelled),true);
 await page.evaluate(blocked=>{fx.hold='';fx.preflight=blocked?'blocked':'ok';replyNative(held.shift());},blocked);await page.waitForFunction(()=>!orange.state.launchAttempt&&!orange.state.pendingMutations);
 assert.equal(await page.evaluate(()=>orange.state.preflight),null,'stale success and blocked reports stay retired');assert.equal(await page.evaluate(()=>orange.state.launchFeedback.includes('请在游戏中核对结果')),false);
 }finally{await page.close();}}});
test('required context invalidation retires the prior report as well as a late reply',async b=>{const{page}=await setup(b);try{await page.locator('#launch').click();await page.waitForFunction(()=>!orange.state.launchAttempt&&!!orange.state.preflight);await page.evaluate(()=>fx.hold='launch');await page.locator('#launch').click();await page.waitForFunction(()=>held.some(m=>m.action==='launch'));await route(page,'memory');await page.locator('#memory-number').fill('12');assert.equal(await page.evaluate(()=>orange.state.preflight),null);await page.evaluate(()=>{fx.hold='';replyNative(held.shift());});await page.waitForFunction(()=>!orange.state.launchAttempt);assert.equal(await page.evaluate(()=>orange.state.preflight),null);}finally{await page.close();}});
test('an invalidated attempt cannot submit after a delayed begin even if target is restored',async b=>{const{page}=await setup(b);try{await page.evaluate(()=>fx.hold='startupBegin');await page.locator('#launch').click();await page.waitForFunction(()=>held.some(m=>m.action==='startupBegin'));await page.locator('#launch-target-kind').selectOption('server');await page.locator('#launch-target-kind').selectOption('normal');assert.equal(await page.evaluate(()=>orange.state.launchAttempt.cancelled),true);await page.evaluate(()=>{fx.hold='';replyNative(held.shift());});await page.waitForFunction(()=>!orange.state.launchAttempt);assert.equal(await page.evaluate(()=>sent.some(m=>m.action==='launch'||m.action==='profileLaunch'||m.action==='playProfileApply')),false);assert.equal(await page.evaluate(()=>sent.some(m=>m.action==='startupCancel')),true);}finally{await page.close();}});
module.exports={setup,route,chromium};
if(require.main===module)(async()=>{const browser=await chromium.launch({channel:process.env.ORANGE_BROWSER_CHANNEL||'msedge',headless:true});let failed=0;try{for(const t of tests.filter(t=>!process.env.OZL_TEST_FILTER||t.name.includes(process.env.OZL_TEST_FILTER))){try{await t.run(browser);console.log('PASS '+t.name);}catch(e){failed++;console.error('FAIL '+t.name+'\n'+e.stack);}}}finally{await browser.close();}console.log(`${tests.filter(t=>!process.env.OZL_TEST_FILTER||t.name.includes(process.env.OZL_TEST_FILTER)).length-failed}/${tests.filter(t=>!process.env.OZL_TEST_FILTER||t.name.includes(process.env.OZL_TEST_FILTER)).length} experience UI groups passed`);if(failed)process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1});
